const { accessSync, constants } = await import('node:fs');
const pdfPath = process.env.PDF_PATH;
if (!pdfPath) { throw new Error('Missing PDF_PATH env var'); }
try { accessSync(pdfPath, constants.R_OK); } catch (e) { throw new Error('Cannot read PDF file at ' + pdfPath); }
globalThis.pdfPath = pdfPath;

const { PDFDocument } = (await import('pdf-lib')).default || await import('pdf-lib');
const { readFileSync } = await import('node:fs');
const data = readFileSync(globalThis.pdfPath);
const pdfDoc = await PDFDocument.load(data);
let title = '';
if (typeof pdfDoc.getTitle === 'function') { title = pdfDoc.getTitle(); }
globalThis.heading = title || '';
